public int pending(String consumer) {
    int count = 0;
    for (Subscription s : subscriptions) {
        if (s.consumer.equals(consumer)) {
            for (Entry e : log) {
                if (e.message.topic().equals(s.topic) && !acknowledged.getOrDefault(consumer, Set.of()).contains(e.seq)) {
                    count++;
                }
            }
        }
    }
    return count;
}

