    long[] window = limiter.windows.computeIfAbsent(request.clientId(), k -> new long[] {now, 0});
    if (now - window[0] >= GatewayContract.WINDOW_MILLIS) {
        window[0] = now;
        window[1] = 0;
    }
    if (window[1] >= limiter.limit) {
        return answer(429, "RATE_LIMIT_EXCEEDED");
