ServiceResult<Resolved> resolve(CallContext context, Query request) {
    long now = context.bus().clock().now();
    List<Row> all = repository.list(request.service());
    if (all.isEmpty()) {
        return ServiceResult.failure("UNKNOWN_SERVICE");
    }
    List<Row> healthy = all.stream().filter(r -> isHealthy(r, now)).toList();
    if (healthy.isEmpty()) {
        return ServiceResult.failure("NO_HEALTHY_INSTANCE");
    }
    Map<String, Integer> positions = state.of("registry.roundRobin", HashMap::new);
    int next = positions.merge(request.service(), 1, Integer::sum) - 1;
    Row chosen = healthy.get(next % healthy.size());
    return ServiceResult.ok(new Resolved(chosen.instance(), chosen.address()));
}

Applied next(ServiceName service, String instance) {
    String key = instance == null ? null : service.id() + "/" + instance;
    if (key != null && instanceBehaviours.containsKey(key)) {
        return apply(instanceBehaviours.get(key), instanceCallsSeen.merge(key, 1, Integer::sum));
    }
    return next(service);
}

private void check(String sql) {
    Matcher m = TABLE.matcher(sql);
    while (m.find()) {
        String table = m.group();
        if (!owner.ownedTables().contains(table)) {
            String owningService = Arrays.stream(ServiceName.values()).filter(s -> s.ownedTables().contains(table)).map(ServiceName::id).findFirst().orElse("nobody");
            throw new OwnershipViolation("The " + owner.id() + " service may not touch " + table + ", which belongs to " + owningService);
        }
    }
}

ServiceResult<OrderView> placeWithOutbox(CallContext context, OutboxOrder request) {
    long orderRef = db.local(ServiceName.ORDER, () -> {
        long id = repository.insertOrder(request.userRef(), request.productRef(), request.quantity(), "PLACED", null);
        repository.insertOutbox("ob-" + id, "order-" + id, "OrderPlaced", "orderRef=" + id);
        if (request.failAfterWrite()) {
            throw new IllegalStateException("injected failure before the transaction commits");
        }
        return id;
    });
    return ServiceResult.ok(new OrderView(orderRef, "PLACED", BigDecimal.ZERO));
}

ServiceResult<Relayed> relayOutbox(CallContext context, Relay request) {
    List<OutboxRow> pending = repository.pendingOutbox();
    int published = 0;
    for (OutboxRow row : pending) {
        events.publishWithId("orders", row.eventType(), Long.parseLong(row.aggregate().substring("order-".length())), row.messageId());
        published++;
        if (request.crashAfterPublish()) {
            throw new IllegalStateException("injected crash after publishing and before marking the row");
        }
        db.local(ServiceName.ORDER, () -> {
            repository.markOutboxPublished(row.id());
            return null;
        });
    }
    return ServiceResult.ok(new Relayed(published, repository.pendingOutbox().size()));

private SagaView compensate(ServiceBus bus, long orderRef, long productRef, List<String> completed) {
    boolean failed = false;
    for (int i = completed.size() - 1; i >= 0; i--) { // reverse order
        String step = "COMPENSATE_" + completed.get(i);
        int seq = begin(orderRef, step);
        CallResult<?> result = compensation(bus, orderRef, step);
        failed |= !result.isSuccess();
        finish(orderRef, seq, result.isSuccess() ? "COMPENSATED" : "COMPENSATION_FAILED", result.isSuccess() ? "reversed by a new business operation" : describe(result));
    }
    return end(orderRef, failed ? "COMPENSATION_FAILED" : "CANCELLED");

